DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Rotary Surface Grinding$q$, 12, 1),
    ($q$Machining - Straight Bevel Gear Cutting$q$, 13, 1),
    ($q$Machining - Spiral Bevel Gear Cutting$q$, 13, 1),
    ($q$Machining - Shaping$q$, 15, 1),
    ($q$Machining - Automated Deburring$q$, 3, 1),
    ($q$Machining - Drill Press$q$, 9, 1),
    ($q$Machining - Stock Prep Mill$q$, 11, 1),
    ($q$Machining - Stock Prep Lathe$q$, 14, 1),
    ($q$Machining - Bench Operation$q$, 3, 1),
    ($q$Machining - Routering$q$, 6, 2)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1030: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
